372	function isAssistantLikeMessage(message: unknown): boolean {
373	  const type = getMessageType(message);
374	  if (!type) return true;
375	  return (
376	    type.includes('ai') ||
377	    type.includes('assistant') ||
378	    type.includes('chat') ||
379	    type.includes('constructor')
380	  );
