420	function compactFinalAnswer(answer: string): string {
421	  return redactSecrets(answer)
422	    .replace(/\u0000/g, '')
423	    .replace(/\r\n/g, '\n')
424	    .replace(/[ \t]+\n/g, '\n')
425	    .trim();
