1012	  const text = String(value ?? '');
1013	  return `"${redactSecrets(text).replace(/"/g, '""')}"`;
1014	}
1015	
1016	function writeFailureCsv(path: string, failures: SuiteSummary['failures']): void {
1017	  const header = [
1018	    'run_id',
1019	    'question_id',
1020	    'question',
1021	    'expected',
1022	    'actual',
1023	    'category',
1024	    'reason',
1025	    'tools',
1026	    'stop_reason',
1027	  ];
1028	
1029	  const rows = failures.map((f) =>
1030	    [
1031	      f.runId,
1032	      f.questionId,
1033	      f.question,
1034	      f.expected,
1035	      f.actual,
1036	      f.category,
1037	      f.reason,
1038	      f.tools,
1039	      f.stopReason,
1040	    ]
1041	      .map(csvEscape)
1042	      .join(','),
1043	  );
1044	
1045	  writeFileSync(path, `${header.join(',')}\n${rows.join('\n')}\n`);
1046	}
1047	
1048	function hasSecret(text: string): boolean {
1049	  return redactSecrets(text) !== text;
1050	}
1051	
1052	function scanRepoForSecrets(root: string): Array<{ file: string; finding: string }> {
1053	  const findings: Array<{ file: string; finding: string }> = [];
1054	  const skipDirs = new Set([
1055	    '.git',
1056	    'node_modules',
1057	    '.next',
1058	    'dist',
1059	    'build',
1060	    'coverage',
1061	    '.turbo',
1062	    '.cache',
1063	    '__pycache__',
1064	  ]);
1065	
1066	  const allowedExtensions = new Set([
1067	    '',
1068	    '.env',
1069	    '.txt',
1070	    '.log',
1071	    '.json',
1072	    '.jsonl',
1073	    '.ts',
1074	    '.tsx',
1075	    '.js',
1076	    '.jsx',
1077	    '.mjs',
1078	    '.cjs',
1079	    '.md',
1080	    '.yml',
1081	    '.yaml',
1082	    '.toml',
1083	    '.sh',
1084	  ]);
1085	
1086	  function walk(dir: string, depth: number): void {
1087	    if (depth > 8 || findings.length >= 50) return;
1088	
1089	    let entries: string[];
1090	    try {
1091	      entries = readdirSync(dir);
1092	    } catch {
1093	      return;
1094	    }
1095	
1096	    for (const entry of entries) {
1097	      const full = join(dir, entry);
1098	      let st;
1099	      try {
1100	        st = statSync(full);
1101	      } catch {
1102	        continue;
1103	      }
1104	
1105	      if (st.isDirectory()) {
1106	        if (skipDirs.has(entry)) continue;
1107	        walk(full, depth + 1);
1108	        continue;
1109	      }
1110	
1111	      if (!st.isFile()) continue;
1112	      if (st.size > 2_000_000) continue;
1113	
1114	      const ext = extname(entry).toLowerCase();
1115	      const base = basename(entry).toLowerCase();
1116	      if (!allowedExtensions.has(ext) && !base.startsWith('.env')) continue;
1117	
1118	      try {
1119	        const text = readFileSync(full, 'utf8');
1120	        if (hasSecret(text)) {
1121	          findings.push({
1122	            file: relative(root, full),
1123	            finding: 'possible secret detected and redacted',
1124	          });
1125	        }
1126	      } catch {
1127	        // Ignore binary/unreadable files.
1128	      }
1129	    }
1130	  }
1131	
1132	  walk(root, 0);
1133	  return findings;
1134	}
1135	
1136	async function main(): Promise<void> {
1137	  ensureDeterministicEnv();
1138	
1139	  const suiteStartedAt = new Date();
1140	  const suiteStartMs = Date.now();
1141	  const suiteDeadline = suiteStartMs + TOTAL_TIMEOUT_MS;
1142	  const runDir = join(LOG_ROOT, timestampForPath(suiteStartedAt));
1143	
1144	  mkdirSync(runDir, { recursive: true });
1145	
1146	  const rawLogPath = join(runDir, 'raw.log');
1147	  const jsonlPath = join(runDir, 'observability.jsonl');
1148	  const summaryPath = join(runDir, 'summary.json');
1149	  const failuresCsvPath = join(runDir, 'failures.csv');
1150	
1151	  const write = (text: string): void => {
1152	    const clean = redactSecrets(text);
1153	    process.stdout.write(clean);
1154	    appendFileSync(rawLogPath, clean);
1155	  };
1156	
1157	  const writeLine = (text = ''): void => write(`${text}\n`);
1158	
1159	  let dbInitialized = false;
1160	  let totalPassed = 0;
1161	  let totalAttempted = 0;
1162	  const failures: SuiteSummary['failures'] = [];
1163	
1164	  try {
1165	    writeLine(`run_dir: ${runDir}`);
1166	    writeLine(`security: terminal and file logs are redacted`);
1167	
1168	    if (SECRET_SCAN) {
1169	      const secretFindings = scanRepoForSecrets(process.cwd());
1170	      if (secretFindings.length > 0) {
1171	        writeLine(`security: ${secretFindings.length} possible secret-bearing file(s) found; values not printed`);
1172	        appendFileSync(join(runDir, 'secret-scan.json'), jsonLine(secretFindings));
1173	      } else {
1174	        writeLine('security: no obvious secrets found in scanned text files');
1175	      }
1176	    }
1177	
1178	    await initDb();
1179	    dbInitialized = true;
1180	
1181	    const basePrompt = await buildSystemPrompt();
1182	    const prompt = `${basePrompt.trim()}\n\n${TEST_MODE_PROMPT_SUFFIX}\n`;
1183	    const modelId = getModel();
1184	
1185	    writeLine();
1186	    writeLine(`┌─ ${modelId} — ${RUNS_PER_QUESTION} runs × ${QUESTIONS.length} questions`);
1187	    writeLine(`├─ timeout: ${TOTAL_TIMEOUT_MS / 1000}s wall, ${RUN_TIMEOUT_MS / 1000}s per run`);
1188	    writeLine(`├─ max tool calls per run: ${MAX_TOOL_CALLS}`);
1189	    writeLine(`└${'─'.repeat(70)}`);
1190	    writeLine();
1191	
1192	    for (const q of QUESTIONS) {
1193	      if (Date.now() >= suiteDeadline) {
1194	        writeLine(`⏰ Wall timeout — stopping before ${q.id}`);
1195	        break;
1196	      }
1197	
1198	      writeLine();
1199	      writeLine(`══════════ ${q.id} (${q.tier}): ${q.q} ══════════`);
1200	      writeLine();
1201	
1202	      let questionPassed = 0;
1203	      let questionRuns = 0;
1204	
1205	      for (let runNumber = 1; runNumber <= RUNS_PER_QUESTION && Date.now() < suiteDeadline; runNumber++) {
1206	        questionRuns++;
1207	        writeLine(`── run ${runNumber}/${RUNS_PER_QUESTION} ──`);
1208	
1209	        const trace = await streamQuestion({
1210	          q,
1211	          runNumber,
1212	          prompt,
1213	          model: modelId,
1214	          suiteDeadline,
1215	          write,
1216	        });
1217	
1218	        totalAttempted++;
1219	
1220	        if (trace.evaluator.passed) {
1221	          totalPassed++;
1222	          questionPassed++;
1223	        } else {
1224	          failures.push({
1225	            runId: trace.runId,
1226	            questionId: trace.questionId,
1227	            question: trace.question,
1228	            expected: trace.expected,
1229	            actual: compact(trace.finalAnswerEmitted, 500),
1230	            category: trace.evaluator.failureCategory,
1231	            reason: trace.evaluator.verdict,
1232	            tools: trace.toolCalls.length,
1233	            stopReason: trace.stop.reason,
1234	          });
1235	        }
1236	
1237	        appendFileSync(jsonlPath, jsonLine(trace));
1238	
1239	        const status = trace.evaluator.passed ? '✅ PASS' : `❌ FAIL [${trace.evaluator.failureCategory}]`;
1240	        writeLine();
1241	        writeLine(
1242	          `${status} tools:${trace.toolCalls.length} stop:${trace.stop.reason} latency:${trace.timing.latencyMs ?? 0}ms`,
1243	        );
1244	
1245	        if (!trace.evaluator.passed) {
1246	          writeLine(`${TAB}reason: ${compact(trace.evaluator.verdict, 240)}`);
1247	          writeLine(`${TAB}actual: ${compact(trace.finalAnswerEmitted, 240)}`);
1248	        }
1249	
1250	        writeLine();
1251	      }
1252	
1253	      writeLine(`── ${q.id} result: ${questionPassed}/${questionRuns} pass ──`);
1254	      writeLine();
1255	    }
1256	
1257	    const elapsedSec = Math.round((Date.now() - suiteStartMs) / 1000);
1258	    const totalExpected = QUESTIONS.length * RUNS_PER_QUESTION;
1259	    const allPassed = totalAttempted === totalExpected && totalPassed === totalAttempted;
1260	
1261	    const summary: SuiteSummary = {
1262	      startedAt: suiteStartedAt.toISOString(),
1263	      endedAt: new Date().toISOString(),
1264	      elapsedSec,
1265	      model: getModel(),
1266	      totalPassed,
1267	      totalAttempted,
1268	      totalExpected,
1269	      allPassed,
1270	      runDir,
1271	      failures,
1272	    };
1273	
1274	    writeFileSync(summaryPath, `${JSON.stringify(toJsonSafe(summary), null, 2)}\n`);
1275	    writeFailureCsv(failuresCsvPath, failures);
1276	
1277	    writeLine();
1278	    writeLine('═'.repeat(70));
1279	    writeLine(`RESULT: ${totalPassed}/${totalAttempted} PASS in ${elapsedSec}s`);
1280	    writeLine(`EXPECTED RUNS: ${totalExpected}`);
1281	    writeLine(`ALL PASSED: ${allPassed ? 'yes' : 'no'}`);
1282	    writeLine(`RAW LOG: ${rawLogPath}`);
1283	    writeLine(`JSONL TRACE: ${jsonlPath}`);
1284	    writeLine(`SUMMARY: ${summaryPath}`);
1285	    writeLine(`FAILURES CSV: ${failuresCsvPath}`);
1286	    writeLine('═'.repeat(70));
1287	    writeLine();
1288	
1289	    if (!allPassed && EXIT_NONZERO_ON_FAIL) {
1290	      process.exitCode = 1;
1291	    }
1292	  } catch (e) {
1293	    const message = e instanceof Error ? e.stack || e.message : String(e);
1294	    writeLine();
1295	    writeLine(`FATAL: ${compact(message, 2000)}`);
1296	    process.exitCode = 1;
1297	  } finally {
1298	    if (dbInitialized) {
1299	      try {
1300	        await closeDb();
1301	      } catch (e) {
1302	        const message = e instanceof Error ? e.message : String(e);
1303	        appendFileSync(rawLogPath, `closeDb error: ${compact(message, 500)}\n`);
1304	      }
1305	    }
1306	  }
1307	}
1308	
1309	main();

