1	import { getTables, query } from '../db.js';
2	import { ERROR_PREFIX, formatErrorForLLM, withRetry } from './retry.js';
3	
4	const BLOCKED_SQL_PATTERNS = [
5	  /\b(insert|update|delete|merge|create|drop|alter|truncate|attach|detach)\b/i,
6	  /\b(copy|load|install|set|call|pragma|vacuum|checkpoint|export|import)\b/i,
7	  /\b(read_csv|read_json|read_parquet|read_text|glob|httpfs)\s*\(/i,
8	];
9	
10	function stripSqlComments(sql: string): string {
11	  return sql
12	    .replace(/--.*$/gm, '')
13	    .replace(/\/\*[\s\S]*?\*\//g, '')
14	    .trim();
15	}
16	
17	export function validateReadOnlySql(sql: string): string | null {
18	  const stripped = stripSqlComments(sql).replace(/;\s*$/, '').trim();
19	  if (!stripped) {
20	    return 'SQL is empty.';
21	  }
22	  if (stripped.includes(';')) {
23	    return 'Only one SQL statement is allowed.';
24	  }
25	  if (!/^(select|with|describe)\b/i.test(stripped)) {
26	    return 'Only read-only SELECT, WITH, or DESCRIBE statements are allowed.';
27	  }
28	  for (const pattern of BLOCKED_SQL_PATTERNS) {
29	    if (pattern.test(stripped)) {
30	      return 'SQL contains a blocked statement or external-access function.';
31	    }
32	  }
33	  return null;
34	}
35	
36	export function extractSql(text: string): string | null {
37	  const match = text.match(/```sql\n([\s\S]*?)```/);
38	  if (match) {
39	    return (match[1] ?? '').trim();
40	  }
41	
42	  const cleaned = text
43	    .replace(/<\|(?:channel|message|start|end|call)\|>/g, '\n')
44	    .replace(/to=(?:container\.exec|repo_browser|duckdb|[^\s]+)/g, ' ');
45	  const fallback = cleaned.match(/\b(select|with|describe)\b[\s\S]*?(?:;|\n\s*\n|$)/i);
46	  if (!fallback) {
47	    return null;
48	  }
49	
50	  return fallback[0].replace(/;\s*$/, '').trim();
51	}
52	
53	export function extractSqlFromMarkdown(text: string): string[] {
54	  const regex = /```sql\n([\s\S]*?)```/g;
55	  const blocks: string[] = [];
56	  let match: RegExpExecArray | null;
57	  while ((match = regex.exec(text)) !== null) {
58	    blocks.push((match[1] ?? '').trim());
59	  }
60	  return blocks;
61	}
62	
63	function extractTableRefs(sql: string): string[] {
64	  const refs = new Set<string>();
65	  const fromRegex = /\bFROM\s+([a-z_][a-z0-9_]*(?:\s*\.\s*[a-z_][a-z0-9_]*)?)/gi;
66	  const joinRegex = /\bJOIN\s+([a-z_][a-z0-9_]*(?:\s*\.\s*[a-z_][a-z0-9_]*)?)/gi;
67	
68	  for (const regex of [fromRegex, joinRegex]) {
69	    let match: RegExpExecArray | null;
70	    while ((match = regex.exec(sql)) !== null) {
71	      const ref = match[1];
72	      if (ref) {
73	        refs.add(ref.toLowerCase().replace(/\s+/g, ''));
74	      }
75	    }
76	  }
77	  return [...refs];
78	}
79	
80	export interface SchemaValidationError {
81	  type: 'missing_table' | 'missing_column';
82	  message: string;
83	}
84	
85	const SCHEMA_VALIDATION_TABLE_LIMIT = 5;
86	
87	export async function validateSchemaReferences(sql: string): Promise<SchemaValidationError[]> {
88	  const errors: SchemaValidationError[] = [];
89	  const tableRefs = extractTableRefs(sql);
90	
91	  if (tableRefs.length === 0) return errors;
92	  if (tableRefs.length > SCHEMA_VALIDATION_TABLE_LIMIT) return errors;
93	
94	  const existingTables = new Set((await getTables()).map((t) => t.toLowerCase()));
95	
96	  for (const ref of tableRefs) {
97	    if (!existingTables.has(ref) && !existingTables.has(`main.${ref}`)) {
98	      errors.push({
99	        type: 'missing_table',
100	        message: `Table "${ref}" does not exist in the database.`,
101	      });
102	    }
103	  }
104	
105	  return errors;
106	}
107	
